const upsertObservedAddress = `-- name: UpsertObservedAddress :exec
INSERT INTO host_addresses (host_id, address, family, interface, source, first_seen_at, last_seen_at)
VALUES (?, ?, ?, ?, ?, ?, ?)
ON CONFLICT (host_id, address) DO UPDATE SET last_seen_at = excluded.last_seen_at, interface = excluded.interface,
  source = CASE WHEN host_addresses.source = 'configured' THEN 'configured' ELSE excluded.source END
`

type UpsertObservedAddressParams struct {
	HostID      string
	Address     string
	Family      int64
	Interface   string
	Source      string
	FirstSeenAt int64
	LastSeenAt  int64
}

// Never changes the source of an existing address of another kind.
func (q *Queries) UpsertObservedAddress(ctx context.Context, arg UpsertObservedAddressParams) error {
	_, err := q.db.ExecContext(ctx, upsertObservedAddress,
		arg.HostID,
		arg.Address,
		arg.Family,
		arg.Interface,
		arg.Source,
		arg.FirstSeenAt,
		arg.LastSeenAt,
	)
	return err
}

