const useEnrollmentToken = `-- name: UseEnrollmentToken :execrows
UPDATE agent_enrollment_tokens SET used_at = ?, used_by_identity = ?
WHERE id = ? AND used_at IS NULL AND revoked_at IS NULL AND expires_at > ?
`

type UseEnrollmentTokenParams struct {
	UsedAt         sql.NullInt64
	UsedByIdentity sql.NullString
	ID             string
	ExpiresAt      int64
}

// Atomic single use: only an unused, unrevoked, unexpired token matches.
func (q *Queries) UseEnrollmentToken(ctx context.Context, arg UseEnrollmentTokenParams) (int64, error) {
	result, err := q.db.ExecContext(ctx, useEnrollmentToken,
		arg.UsedAt,
		arg.UsedByIdentity,
		arg.ID,
		arg.ExpiresAt,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected()
}
